def _docx_bytes(text: str, with_table=False) -> bytes:
    doc = Document()
    for line in text.split("\n"):
        doc.add_paragraph(line)
    if with_table:
        doc.add_table(rows=1, cols=2).rows[0].cells[0].text = "Python"
    buf = io.BytesIO()
    doc.save(buf)
    return buf.getvalue()


