def test_docx_mirrors_template_features():
    """Professional DOCX: modern Word mode, avatar + contact icons as images, clickable contact links."""
    import zipfile
    data = client.post("/api/export", json={"resume_text": SAMPLE_RESUME, "template": "professional",
                                            "format": "docx"}).content
    with zipfile.ZipFile(io.BytesIO(data)) as zf:
        settings = zf.read("word/settings.xml").decode()
        rels = zf.read("word/_rels/document.xml.rels").decode()
        media = [n for n in zf.namelist() if n.startswith("word/media/")]
    assert 'w:name="compatibilityMode"' in settings and 'w:val="15"' in settings
    assert "mailto:alex.morgan@example.com" in rels and "https://linkedin.com/in/alexmorgan-example" in rels
    assert len(media) >= 4  # initials avatar + email/phone/location/linkedin icons (+ calendar)


def test_pdf_stylesheet_keeps_every_accent_rule():
    """A BOM or mis-decoded bytes at the top of resume.css silently break the first accent rule in PDFs."""
    from app.render_html import render_html
    from app.resume_templates import ACCENTS
    html = render_html(SAMPLE_RESUME, "classic", "blue", for_pdf=True)
    css = html.split("<style>", 1)[1]
    assert css.startswith("/*") and "\ufeff" not in html and "\u00c2" not in html
    for name, hex_color in ACCENTS.items():
        assert f".acc-{name} {{ --accent: {hex_color};" in css


