def test_model_rebuilds_wrapped_pdf_text():
    m = build_model(WRAPPED_PDF_TEXT)
    assert m["name"] == "JANE DOE" and m["headline"].startswith("DevOps Engineer")
    assert {c["kind"] for c in m["contacts"]} >= {"phone", "email", "linkedin", "location"}
    exp = next(s for s in m["sections"] if s["key"] == "experience")
    first, second = exp["entries"]
    assert (first["title"], first["meta"], first["subtitle"], first["date"], first["location"]) == \
        ("DevOps Engineer", "Full-time", "Contoso", "Apr 2024 - Present", "On-site ? Pune")
    assert first["bullets"][0].endswith("and cloud-native workloads.") and len(first["bullets"]) == 2
    assert first["tech"]["value"].endswith("Azure Monitor")
    assert (second["title"], second["subtitle"], second["date"], second["location"]) == \
        ("Cloud Intern", "Fabrikam", "Mar 2023 - Aug 2023", "Pune, India")
    assert second["bullets"][0].endswith("between systems")
    assert next(s for s in m["sections"] if s["key"] == "education")["entries"][0]["date"] == "Jul 2019 - Jul 2023"


