def _fake_ai(monkeypatch, reply: str):
    """Simulate a running Ollama model returning `reply`."""
    async def online(force=False):
        return {"available": True, "model": "qwen2.5:7b", "configured_model": "qwen2.5:7b"}

    async def generate(prompt, *, json_mode=False, temperature=0.4):
        assert "<resume>" in prompt or "<text>" in prompt  # untrusted input is fenced
        return reply
    monkeypatch.setattr(llm, "status", online)
    monkeypatch.setattr(llm, "generate", generate)


