def test_hosted_mode_rate_limit_and_health(monkeypatch):
    """Public deployments: per-IP limits keyed on the proxy-added (right-most) X-Forwarded-For entry."""
    monkeypatch.setattr(main_module, "PUBLIC_MODE", True)
    monkeypatch.setitem(main_module.RATE_LIMITS, "/api/analyze", 2)
    main_module._hits.clear()
    body = {"resume_text": SAMPLE_RESUME}
    spoofed = {"X-Forwarded-For": "1.1.1.1, 203.0.113.7"}
    assert client.post("/api/analyze", json=body, headers=spoofed).status_code == 200
    assert client.post("/api/analyze", json=body, headers={"X-Forwarded-For": "9.9.9.9, 203.0.113.7"}).status_code == 200
    blocked = client.post("/api/analyze", json=body, headers=spoofed)
    assert blocked.status_code == 429 and blocked.json()["detail"] == "err_rate_limited"
    assert client.post("/api/analyze", json=body, headers={"X-Forwarded-For": "198.51.100.1"}).status_code == 200
    assert client.get("/api/health").json()["mode"] == "hosted"
    assert client.get("/healthz").json() == {"status": "ok"}
    main_module._hits.clear()
